//! Convert the legacy JSONC scene document into the Python DSL.

use std::path::Path;

use anyhow::{Context, Result, bail};
use serde_json::Value;

const HEADER: &str = "\
# Generated by `widdgyy --migrate-config`.
# Presentation belongs in styles.css; use cls=... on each node.
from widdgyy import ApiText, Clock, Gif, Grid, HBox, Image, Text, VBox, Video

stickers = [
";

pub fn to_python(value: &Value) -> Result<String> {
    let stickers = value
        .get("stickers")
        .and_then(Value::as_array)
        .context("config must contain a `stickers` array")?;
    let mut output = String::from(HEADER);
    for sticker in stickers {
        output.push_str(&render(sticker, 1)?);
        output.push_str(",\n");
    }
    output.push_str("]\n");
    Ok(output)
}

fn render(value: &Value, indent: usize) -> Result<String> {
    let object = value
        .as_object()
        .context("every sticker must be a JSON object")?;
    let sticker_type = object
        .get("type")
        .and_then(Value::as_str)
        .context("sticker is missing `type`")?
        .to_ascii_lowercase();

    let class;
    let mut positional: Vec<String> = Vec::new();
    let mut arguments: Vec<(String, String)> = Vec::new();
    let mut consumed: Vec<&str> = vec![
        "type", "class", "id", "anchor", "offset_x", "offset_y", "z_index", "style",
    ];

    match sticker_type.as_str() {
        "text" => {
            class = "Text";
            let text = object
                .get("text")
                .cloned()
                .unwrap_or(Value::String(String::new()));
            arguments.push(("text".to_string(), literal(&text)));
            consumed.push("text");
        }
        "clock" => {
            class = "Clock";
            let format = object
                .get("format")
                .cloned()
                .unwrap_or(Value::String("%H:%M:%S".to_string()));
            arguments.push(("format".to_string(), literal(&format)));
            consumed.push("format");
        }
        "api_text" => {
            class = "ApiText";
            let url = object
                .get("url")
                .context("api_text sticker is missing `url`")?;
            arguments.push(("url".to_string(), literal(url)));
            for key in ["template", "fields"] {
                if let Some(value) = object.get(key) {
                    arguments.push((key.to_string(), literal(value)));
                    consumed.push(key);
                }
            }
            consumed.push("url");
        }
        "media" => {
            class = media_class(object.get("path").and_then(Value::as_str).unwrap_or(""));
            let path = object
                .get("path")
                .context("media sticker is missing `path`")?;
            arguments.push(("path".to_string(), literal(path)));
            consumed.push("path");
        }
        "hbox" => class = "HBox",
        "vbox" => class = "VBox",
        "grid" => {
            class = "Grid";
            let columns = object.get("columns").and_then(Value::as_u64).unwrap_or(2);
            arguments.push(("columns".to_string(), columns.to_string()));
            consumed.push("columns");
        }
        other => bail!("unknown sticker type: {other}"),
    }

    if let Some(children) = object.get("children").and_then(Value::as_array) {
        for child in children {
            positional.push(render(child, indent + 1)?);
        }
        consumed.push("children");
    }

    if let Some(classes) = object.get("class") {
        let classes = match classes {
            Value::String(text) => text.clone(),
            Value::Array(items) => items
                .iter()
                .filter_map(Value::as_str)
                .collect::<Vec<_>>()
                .join(" "),
            _ => bail!("`class` must be a string or an array of strings"),
        };
        arguments.push(("cls".to_string(), literal(&Value::String(classes))));
    }
    if let Some(id) = object.get("id") {
        arguments.push(("id".to_string(), literal(id)));
    }
    if let Some(anchor) = object.get("anchor") {
        arguments.push(("anchor".to_string(), literal(anchor)));
    }
    let offset_x = object
        .get("offset_x")
        .and_then(Value::as_f64)
        .unwrap_or(0.0);
    let offset_y = object
        .get("offset_y")
        .and_then(Value::as_f64)
        .unwrap_or(0.0);
    if object.contains_key("offset_x") || object.contains_key("offset_y") {
        arguments.push(("offset".to_string(), format!("({offset_x}, {offset_y})")));
    }
    if let Some(z_index) = object.get("z_index") {
        arguments.push(("z".to_string(), literal(z_index)));
    }
    if let Some(style) = object.get("style") {
        arguments.push(("style".to_string(), literal(style)));
    }

    for (key, value) in object {
        if consumed.contains(&key.as_str()) {
            continue;
        }
        let name = key.replace('-', "_");
        if !is_identifier(&name) {
            continue;
        }
        arguments.push((name, literal(value)));
    }

    let pad = "    ".repeat(indent);
    let inner = "    ".repeat(indent + 1);
    let mut output = format!("{pad}{class}(\n");
    for child in positional {
        output.push_str(&child);
        output.push_str(",\n");
    }
    for (name, value) in arguments {
        output.push_str(&inner);
        output.push_str(&name);
        output.push('=');
        output.push_str(&value);
        output.push_str(",\n");
    }
    output.push_str(&pad);
    output.push(')');
    Ok(output)
}

fn media_class(path: &str) -> &'static str {
    match Path::new(path)
        .extension()
        .and_then(|extension| extension.to_str())
        .unwrap_or("")
        .to_ascii_lowercase()
        .as_str()
    {
        "mp4" | "mkv" | "webm" | "avi" | "mov" | "m4v" => "Video",
        "gif" => "Gif",
        _ => "Image",
    }
}

fn is_identifier(name: &str) -> bool {
    let mut chars = name.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    (first.is_ascii_alphabetic() || first == '_')
        && chars.all(|ch| ch.is_ascii_alphanumeric() || ch == '_')
}

fn literal(value: &Value) -> String {
    match value {
        Value::Null => "None".to_string(),
        Value::Bool(value) => {
            if *value {
                "True".to_string()
            } else {
                "False".to_string()
            }
        }
        Value::Number(number) => number.to_string(),
        Value::String(text) => serde_json::to_string(text).unwrap_or_else(|_| "\"\"".to_string()),
        Value::Array(items) => {
            let items: Vec<String> = items.iter().map(literal).collect();
            format!("[{}]", items.join(", "))
        }
        Value::Object(map) => {
            let entries: Vec<String> = map
                .iter()
                .map(|(key, value)| {
                    format!(
                        "{}: {}",
                        serde_json::to_string(key).unwrap_or_else(|_| "\"\"".to_string()),
                        literal(value)
                    )
                })
                .collect();
            format!("{{{}}}", entries.join(", "))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn emits_python_for_each_sticker_type() {
        let value: Value = json5::from_str(
            r#"{
                stickers: [
                    { type: "media", path: "assets/wall.mp4", class: "background", z_index: -1 },
                    { type: "hbox", class: "row", offset_x: 0, offset_y: -10, children: [
                        { type: "clock", format: "%H:%M" },
                        { type: "api_text", url: "https://example.com", template: "{t}", fields: { t: "a.b" } }
                    ] },
                    { type: "text", text: "hi", class: "note" }
                ]
            }"#,
        )
        .unwrap();
        let python = to_python(&value).unwrap();
        assert!(python.contains("Video("));
        assert!(python.contains("path=\"assets/wall.mp4\""));
        assert!(python.contains("HBox("));
        assert!(python.contains("Clock("));
        assert!(python.contains("ApiText("));
        assert!(python.contains("Text("));
        assert!(python.contains("cls=\"row\""));
        assert!(python.contains("offset=(0, -10)"));
    }

    #[test]
    fn python_literals_are_valid_python() {
        assert_eq!(literal(&Value::Bool(true)), "True");
        assert_eq!(literal(&Value::Null), "None");
        assert_eq!(literal(&Value::from(3)), "3");
    }
}
